pub const Quantifier = enum(u2) { one, optional, variadic };
pub const OperandDesc = struct { kind: OperandKind, quantifier: Quantifier = .one };

/// The operand descriptors of `op` (empty for an unknown opcode).
pub fn operands(op: Opcode) []const OperandDesc {
    return switch (op) {
        .OpNop => &.{},
        .OpUndef => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult } },
        .OpSourceContinued => &.{.{ .kind = .LiteralString }},
        .OpSource => &.{ .{ .kind = .SourceLanguage }, .{ .kind = .LiteralInteger }, .{ .kind = .IdRef, .quantifier = .optional }, .{ .kind = .LiteralString, .quantifier = .optional } },
        .OpSourceExtension => &.{.{ .kind = .LiteralString }},
        .OpName => &.{ .{ .kind = .IdRef }, .{ .kind = .LiteralString } },
        .OpMemberName => &.{ .{ .kind = .IdRef }, .{ .kind = .LiteralInteger }, .{ .kind = .LiteralString } },
        .OpString => &.{ .{ .kind = .IdResult }, .{ .kind = .LiteralString } },
        .OpLine => &.{ .{ .kind = .IdRef }, .{ .kind = .LiteralInteger }, .{ .kind = .LiteralInteger } },
        .OpExtension => &.{.{ .kind = .LiteralString }},
        .OpExtInstImport => &.{ .{ .kind = .IdResult }, .{ .kind = .LiteralString } },
        .OpExtInst => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .IdRef }, .{ .kind = .LiteralExtInstInteger }, .{ .kind = .IdRef, .quantifier = .variadic } },
        .OpMemoryModel => &.{ .{ .kind = .AddressingModel }, .{ .kind = .MemoryModel } },
        .OpEntryPoint => &.{ .{ .kind = .ExecutionModel }, .{ .kind = .IdRef }, .{ .kind = .LiteralString }, .{ .kind = .IdRef, .quantifier = .variadic } },
        .OpExecutionMode => &.{ .{ .kind = .IdRef }, .{ .kind = .ExecutionMode } },
        .OpCapability => &.{.{ .kind = .Capability }},
        .OpTypeVoid => &.{.{ .kind = .IdResult }},
        .OpTypeBool => &.{.{ .kind = .IdResult }},
        .OpTypeInt => &.{ .{ .kind = .IdResult }, .{ .kind = .LiteralInteger }, .{ .kind = .LiteralInteger } },
        .OpTypeFloat => &.{ .{ .kind = .IdResult }, .{ .kind = .LiteralInteger }, .{ .kind = .FPEncoding, .quantifier = .optional } },
        .OpTypeVector => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef }, .{ .kind = .LiteralInteger } },
        .OpTypeMatrix => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef }, .{ .kind = .LiteralInteger } },
        .OpTypeImage => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef }, .{ .kind = .Dim }, .{ .kind = .LiteralInteger }, .{ .kind = .LiteralInteger }, .{ .kind = .LiteralInteger }, .{ .kind = .LiteralInteger }, .{ .kind = .ImageFormat }, .{ .kind = .AccessQualifier, .quantifier = .optional } },
        .OpTypeSampler => &.{.{ .kind = .IdResult }},
        .OpTypeSampledImage => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef } },
        .OpTypeArray => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef }, .{ .kind = .IdRef } },
        .OpTypeRuntimeArray => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef } },
        .OpTypeStruct => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef, .quantifier = .variadic } },
        .OpTypeOpaque => &.{ .{ .kind = .IdResult }, .{ .kind = .LiteralString } },
        .OpTypePointer => &.{ .{ .kind = .IdResult }, .{ .kind = .StorageClass }, .{ .kind = .IdRef } },
        .OpTypeFunction => &.{ .{ .kind = .IdResult }, .{ .kind = .IdRef }, .{ .kind = .IdRef, .quantifier = .variadic } },
        .OpTypeEvent => &.{.{ .kind = .IdResult }},
        .OpTypeDeviceEvent => &.{.{ .kind = .IdResult }},
        .OpTypeReserveId => &.{.{ .kind = .IdResult }},
        .OpTypeQueue => &.{.{ .kind = .IdResult }},
        .OpTypePipe => &.{ .{ .kind = .IdResult }, .{ .kind = .AccessQualifier } },
        .OpTypeForwardPointer => &.{ .{ .kind = .IdRef }, .{ .kind = .StorageClass } },
        .OpConstantTrue => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult } },
        .OpConstantFalse => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult } },
        .OpConstant => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .LiteralContextDependentNumber } },
        .OpConstantComposite => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .IdRef, .quantifier = .variadic } },
        .OpConstantSampler => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .SamplerAddressingMode }, .{ .kind = .LiteralInteger }, .{ .kind = .SamplerFilterMode } },
        .OpConstantNull => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult } },
        .OpSpecConstantTrue => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult } },
        .OpSpecConstantFalse => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult } },
        .OpSpecConstant => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .LiteralContextDependentNumber } },
        .OpSpecConstantComposite => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .IdRef, .quantifier = .variadic } },
        .OpSpecConstantOp => &.{ .{ .kind = .IdResultType }, .{ .kind = .IdResult }, .{ .kind = .LiteralSpecConstantOpInteger } },
