/// The name of `value` in a value enum `kind`.
pub fn valueName(kind: OperandKind, value: u32) ?[]const u8 {
    return switch (kind) {
        .SourceLanguage => std.enums.tagName(SourceLanguage, @enumFromInt(value)),
        .ExecutionModel => std.enums.tagName(ExecutionModel, @enumFromInt(value)),
        .AddressingModel => std.enums.tagName(AddressingModel, @enumFromInt(value)),
        .MemoryModel => std.enums.tagName(MemoryModel, @enumFromInt(value)),
        .ExecutionMode => std.enums.tagName(ExecutionMode, @enumFromInt(value)),
        .StorageClass => std.enums.tagName(StorageClass, @enumFromInt(value)),
        .Dim => std.enums.tagName(Dim, @enumFromInt(value)),
        .SamplerAddressingMode => std.enums.tagName(SamplerAddressingMode, @enumFromInt(value)),
        .SamplerFilterMode => std.enums.tagName(SamplerFilterMode, @enumFromInt(value)),
        .ImageFormat => std.enums.tagName(ImageFormat, @enumFromInt(value)),
        .ImageChannelOrder => std.enums.tagName(ImageChannelOrder, @enumFromInt(value)),
        .ImageChannelDataType => std.enums.tagName(ImageChannelDataType, @enumFromInt(value)),
        .FPRoundingMode => std.enums.tagName(FPRoundingMode, @enumFromInt(value)),
