}

/// The name of `bit` in a bit enum `kind`.
pub fn bitName(kind: OperandKind, bit: u5) ?[]const u8 {
    return switch (kind) {
        .ImageOperands => fieldName(ImageOperands, bit),
        .FPFastMathMode => fieldName(FPFastMathMode, bit),
        .SelectionControl => fieldName(SelectionControl, bit),
        .LoopControl => fieldName(LoopControl, bit),
        .FunctionControl => fieldName(FunctionControl, bit),
        .MemorySemantics => fieldName(MemorySemantics, bit),
        .MemoryAccess => fieldName(MemoryAccess, bit),
        .KernelProfilingInfo => fieldName(KernelProfilingInfo, bit),
        .RayFlags => fieldName(RayFlags, bit),
        .FragmentShadingRate => fieldName(FragmentShadingRate, bit),
        .RawAccessChainOperands => fieldName(RawAccessChainOperands, bit),
        .CooperativeMatrixOperands => fieldName(CooperativeMatrixOperands, bit),
        .CooperativeMatrixReduce => fieldName(CooperativeMatrixReduce, bit),
        .TensorAddressingOperands => fieldName(TensorAddressingOperands, bit),
        .MatrixMultiplyAccumulateOperands => fieldName(MatrixMultiplyAccumulateOperands, bit),
        .TensorOperands => fieldName(TensorOperands, bit),
        else => null,
    };
}

fn fieldName(comptime T: type, bit: u5) ?[]const u8 {
    switch (bit) {
        inline else => |b| {
            const name = @typeInfo(T).@"struct".fields[b].name;
            return if (name[0] == '_') null else name;
        },
    }
}
